SET default_transaction_read_only = on;
-- #720: daily bars for every ticker in the window (trades, stop-too-wide skips, the ADMITTED magna53 control since 05-05, missed-by-slots names), from before the first 05-05 alert to today. The missed-by-slots ticker is pulled by regex, never a JSON cast — one malformed detail row (finding 8 counts them) must not abort the bars capture under ON_ERROR_STOP.
\copy (WITH names AS (SELECT DISTINCT ticker FROM mi_live_trades WHERE (filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16') OR (skip_reason LIKE 'setup:stop_too_wide%' AND signal_type = 'magna53' AND alert_date >= DATE '2026-05-05') OR (signal_type = 'magna53' AND skip_reason IS NULL AND status NOT IN ('cancelled', 'skipped') AND filled_at IS NOT NULL AND alert_date >= DATE '2026-05-05') UNION SELECT DISTINCT substring(detail from '"ticker": *"([A-Za-z.-]+)"') FROM mi_audit_log WHERE event_type = 'breakout_v1_missed_by_slots' AND detail ~ '"ticker": *"') SELECT d.ticker, d.trade_date, d.open_price, d.high_price, d.low_price, d.close, d.volume FROM mi_daily_closes d JOIN names n ON n.ticker = d.ticker WHERE d.trade_date >= DATE '2026-03-20' ORDER BY d.ticker, d.trade_date) TO STDOUT WITH CSV HEADER
